//! Fixed synthetic vectors generated by Circom's wasm witness calculator.
use openac_age::{calculate_witness, ZkProofError};
use sha2::{Digest, Sha256};
use std::{fs, path::Path};

#[test]
fn graph_hash_mismatch_is_rejected_before_reading_inputs() {
    let temporary = tempfile::tempdir().unwrap();
    fs::create_dir(temporary.path().join("graphs")).unwrap();
    fs::write(temporary.path().join("graphs/show.graph"), vec![0; 551_178]).unwrap();
    assert!(matches!(
        calculate_witness(temporary.path().to_string_lossy().into_owned(), false),
        Err(ZkProofError::InvalidInput { .. })
    ));
}

#[test]
#[ignore = "Requires pinned graphs and prepare.py synthetic upstream fixtures"]
fn pinned_graphs_match_circom_wasm_vectors() {
    let assets = std::env::var_os("OPENAC_TEST_ASSETS").expect("Verified public assets");
    let inputs =
        Path::new(env!("CARGO_MANIFEST_DIR")).join(".cache/zkid/wallet-unit-poc/circom/inputs");
    for (name, prepare, expected, values) in [
        (
            "jwt",
            true,
            "a3ac60db590b8e8e0e3d5483febda90bf8c89a73c2df9be4108a13c51ea149ac",
            1_523_033,
        ),
        (
            "show",
            false,
            "53538ff17f49eb1a9a1615e3794f3a257ff4e88f67f4d02f1ab4f3b599389ef8",
            18_890,
        ),
    ] {
        let temporary = tempfile::tempdir().unwrap();
        fs::create_dir(temporary.path().join("graphs")).unwrap();
        let graph = if prepare {
            "jwt_2k.graph"
        } else {
            "show.graph"
        };
        let source = Path::new(&assets).join("graphs").join(graph);
        let target = temporary.path().join("graphs").join(graph);
        if fs::hard_link(&source, &target).is_err() {
            fs::copy(source, target).unwrap();
        }
        fs::copy(
            inputs.join(format!("{name}/2k/default.json")),
            temporary.path().join(format!("{name}_input.json")),
        )
        .unwrap();
        let witness =
            calculate_witness(temporary.path().to_string_lossy().into_owned(), prepare).unwrap();
        assert!(format!("{:x}", Sha256::digest(&witness)) == expected);
        assert_eq!(
            ecdsa_spartan2::utils::parse_witness(&witness)
                .unwrap()
                .len(),
            values
        );
    }
}
